pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newConfig, address manager, address asset, uint256 amount) public {
        vm.assume(newConfig != address(0));
        vm.assume(manager != address(0));
        vm.assume(newConfig != manager);

        // set up the new config as a contract that grants MANAGER role to 'manager' and supports 'asset'
        vm.mockCall(
            newConfig,
            abi.encodeWithSelector(0x91d14854, keccak256("MANAGER"), manager), // hasRole
            abi.encode(true)
        );
        vm.mockCall(
            newConfig,
            abi.encodeWithSelector(0x9be918e6, asset), // isSupportedAsset
            abi.encode(true)
        );

        // set up the current config to recognize admin role (DEFAULT_ADMIN_ROLE) for this contract
        address currentConfig = address(c.lrtConfig());
        vm.mockCall(
            currentConfig,
            abi.encodeWithSelector(0x91d14854, bytes32(0), address(this)), // hasRole
            abi.encode(true)
        );

        c.updateLRTConfig(newConfig);

        // Now, manager should be able to call a function gated by onlyLRTManager
        // (which checks lrtConfig for MANAGER role)
        vm.prank(manager);
        bool ok = true;
        try c.transferAssetToNodeDelegator(0, asset, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

