pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newConfig, address asset) public {
        vm.assume(newConfig != address(0));
        vm.assume(asset != address(0));
        // Deploy a minimal mock for the new config that implements getContract and isSupportedAsset
        // to exercise getRsETHAmountToMint through the c contract without relying on a real LRTConfig.
        // The key property: after updateLRTConfig, calling getRsETHAmountToMint should not revert
        // because the new config is set. With the bug, lrtConfig remains zero, and the call reverts.
        MockLRTConfig mock = new MockLRTConfig();
        // Grant admin role to this test contract to allow calling updateLRTConfig
        // First, we need to initialize c with a config that respects access control.
        // Since C's initialize sets lrtConfig to the passed address, we need a config that
        // grants DEFAULT_ADMIN_ROLE to address(this) for onlyLRTAdmin modifier.
        // Deploy a real-like config mock that grants the role.
        AdminMockConfig adminConfig = new AdminMockConfig(address(this));
        c.initialize(address(adminConfig));
        // Now update to the new mock config using the actual updateLRTConfig path.
        c.updateLRTConfig(address(mock));
        // Try to call a function that reads lrtConfig and uses getContract, e.g. getRsETHAmountToMint.
        // It requires the asset to be supported, so we set it as supported in the mock.
        mock.setSupportedAsset(asset, true);
        mock.setAssetPrice(asset, 1 ether);
        mock.setRSETHPrice(1 ether);
        // The call should succeed if lrtConfig is updated. If buggy, it remains zero address -> revert.
        bool ok;
        try c.getRsETHAmountToMint(asset, 100) returns (uint256) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

// Minimal mock that implements the ILRTConfig interface methods needed for the test path.
contract MockLRTConfig {
    mapping(address => bool) public isSupportedAsset;
    mapping(address => uint256) public assetPrices;
    uint256 public rsethPrice;
    address public oracleAddr;

    function setSupportedAsset(address asset, bool val) external { isSupportedAsset[asset] = val; }
    function setAssetPrice(address asset, uint256 price) external { assetPrices[asset] = price; }
    function setRSETHPrice(uint256 price) external { rsethPrice = price; }
    function setOracle(address addr) external { oracleAddr = addr; }

    function getContract(bytes32) external view returns (address) {
        return oracleAddr;
    }

    // Additional ILRTConfig required functions stubs
    function rsETH() external view returns (address) { return address(0); }
    function assetStrategy(address) external view returns (address) { return address(0); }
    function depositLimitByAsset(address) external view returns (uint256) { return type(uint256).max; }
    function getLSTToken(bytes32) external view returns (address) { return address(0); }
    function getSupportedAssetList() external view returns (address[] memory) { return new address[](0); }
}

// Helper config that grants DEFAULT_ADMIN_ROLE to a specified address for onlyLRTAdmin checks.
contract AdminMockConfig {
    address admin;
    constructor(address _admin) { admin = _admin; }

    function hasRole(bytes32 role, address account) external view returns (bool) {
        // DEFAULT_ADMIN_ROLE is 0x00
        if (role == bytes32(0) && account == admin) return true;
        // MANAGER role
        if (role == keccak256("MANAGER") && account == admin) return true;
        return false;
    }

    function isSupportedAsset(address) external pure returns (bool) { return false; }
    function getContract(bytes32) external view returns (address) { return address(0); }
    function rsETH() external view returns (address) { return address(0); }
    function assetStrategy(address) external view returns (address) { return address(0); }
    function depositLimitByAsset(address) external view returns (uint256) { return 0; }
    function getLSTToken(bytes32) external view returns (address) { return address(0); }
    function getSupportedAssetList() external view returns (address[] memory) { return new address[](0); }
}

