pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newConfig, address admin) public {
        vm.assume(newConfig != address(0));
        vm.assume(admin != address(0));
        vm.assume(!AddressUpgradeable.isContract(admin));

        // Deploy a minimal config mock that returns true for hasRole(DEFAULT_ADMIN_ROLE, admin)
        MockConfig mock = new MockConfig(newConfig);

        // Initialize C with a dummy config that grants admin role to 'admin'
        address initialConfig = address(new MockConfig(address(0)));
        vm.prank(admin);
        c.initialize(initialConfig);

        // Grant admin role to admin on the initial config (for initialization only)
        // But updateLRTConfig is onlyLRTAdmin which checks DEFAULT_ADMIN_ROLE on current lrtConfig
        // We need admin to have role on the CURRENT config to call updateLRTConfig
        // Override mock to give role to admin
        mock.grantRole(0x00, admin);

        address oldConfig = address(c.lrtConfig());

        vm.prank(admin);
        c.updateLRTConfig(address(mock));

        address currentConfig = address(c.lrtConfig());
        assertTrue(currentConfig == address(mock));
    }
}

contract MockConfig {
    address public target;
    mapping(bytes32 => mapping(address => bool)) public roles;

    constructor(address _target) {
        target = _target;
    }

    function hasRole(bytes32 role, address account) external view returns (bool) {
        return roles[role][account];
    }

    function grantRole(bytes32 role, address account) external {
        roles[role][account] = true;
    }

    function isSupportedAsset(address) external pure returns (bool) {
        return false;
    }

    function depositLimitByAsset(address) external pure returns (uint256) {
        return 0;
    }

    function rsETH() external view returns (address) {
        return target;
    }

    function getContract(bytes32) external view returns (address) {
        return target;
    }

    function assetStrategy(address) external view returns (address) {
        return target;
    }

    function getLSTToken(bytes32) external pure returns (address) {
        return address(0);
    }

    function getSupportedAssetList() external pure returns (address[] memory) {
        return new address[](0);
    }
}

library AddressUpgradeable {
    function isContract(address account) internal view returns (bool) {
        return account.code.length > 0;
    }
}

