pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address lrtConfig, uint256 newMax) public {
        vm.assume(lrtConfig != address(0));
        vm.assume(newMax != 10);
        vm.assume(newMax < type(uint256).max);

        // First initialization
        c.initialize(lrtConfig);

        // Update maxNodeDelegatorCount to a different value
        vm.prank(lrtConfig);
        c.updateMaxNodeDelegatorCount(newMax);

        // Attempt re-initialization with a different config (should revert on reference)
        address newConfig = address(uint160(uint256(keccak256(abi.encode(lrtConfig)))));
        vm.assume(newConfig != address(0));
        bool reinitReverted = false;
        try c.initialize(newConfig) { } catch { reinitReverted = true; }

        uint256 currentMax = c.maxNodeDelegatorCount();
        if (!reinitReverted) {
            // If re-initialization succeeded (buggy), maxNodeDelegatorCount may have been reset to 10
            assertTrue(currentMax == newMax);
        } else {
            // If re-initialization reverted (reference), maxNodeDelegatorCount should stay at newMax
            assertTrue(currentMax == newMax);
        }
    }
}

